import {question,choices} from './math.mjs';
import {createChallenge,challengeDifficulty,recordAnswer,elapse,beginMemoryBoard,completeMemoryBoard,selectMemoryCard,closeMemoryMismatch} from './challenge-engine.mjs';
import {showCheck,showMiss,showStreak,announce,NEXT_DELAY_MS} from './feedback.mjs';

export function mountChallenge(app,{mode,settings,home,award,beep,learning,scores}) {
  const g=createChallenge(mode.id,20),$=s=>app.querySelector(s);
  let q,options=[],bad=[],cards=[],selected=[],matched=new Set(),locked=false,paused=false,disposed=false,scoreSaved=false,bestAtStart=scores.top(mode.id)[0]||0;
  let questionLeft=0,delay=null,delayLeft=0,clock=0,last=performance.now(),questionStarted=last,pausedAt=0,message='',kind='',sessionId=learning.newSessionId();
  const rules={practice:'12 câu, không đếm giờ. Sai: ngắt chuỗi và trừ 5 điểm. Bé vẫn được thử lại và xem gợi ý.',bubble:'Chạm đáp án trước khi hết giờ. Sai hoặc hết giờ: mất 1 mạng, ngắt chuỗi và trừ 5 điểm.',rocket:'Bay trong 60 giây. Sai hoặc quá giờ một câu: trừ thêm 3 giây, ngắt chuỗi và trừ 5 điểm.',mystery:'Tìm số còn thiếu trước khi hết giờ. Sai hoặc hết giờ: mất 1 mạng, ngắt chuỗi và trừ 5 điểm.',memory:'Ghép đúng: +20 điểm. Ghép sai không trừ điểm đã có. Ít lượt sai, thưởng cuối chặng càng cao. Không đếm giờ.'};
  app.innerHTML=`<div class="play-top"><button class="back" id="challenge-back">← Đảo trò chơi</button><span>${mode.icon} ${mode.title}</span><button class="back" id="challenge-pause">Tạm dừng</button></div><section class="play ${mode.color} challenge"><div class="challenge-hud" id="challenge-hud"></div><p class="challenge-rules">${rules[mode.id]}${mode.id==='memory'?'':' Điểm không âm.'}</p><div id="challenge-body"></div><div class="challenge-overlay" id="challenge-overlay" hidden></div></section>`;
  $('#challenge-back').onclick=home;$('#challenge-pause').onclick=togglePause;
  function difficulty(){return challengeDifficulty(g)}
  function hud(){const d=difficulty(),record=g.score>bestAtStart&&g.score>0;$('#challenge-hud').innerHTML=`<div><span>Điểm</span><b>${g.score}</b></div><div class="record ${record?'new-record':''}"><span>${record?'Kỷ lục mới!':'Kỷ lục'}</span><b>${Math.max(bestAtStart,g.score)}</b></div><div><span>Cấp độ</span><b>${d.level}</b></div><div><span>${mode.id==='memory'?'Lượt ghép':'Chuỗi đúng'}</span><b>${mode.id==='memory'?g.attempts:g.streak}</b></div><div><span>${g.lives!==null?'Mạng':mode.id==='memory'?'Cặp đã ghép':'Đã đúng'}</span><b ${g.lives!==null?`aria-label="${g.lives} mạng"`:''}>${g.lives!==null?'♥'.repeat(g.lives)+'♡'.repeat(3-g.lives):g.correct}</b></div>`;const t=$('#question-clock');if(t)t.textContent=Math.ceil(questionLeft)+'s';const bar=$('#question-bar');if(bar)bar.style.width=Math.max(0,questionLeft/d.deadline*100)+'%'}
  function feedback(text,type=''){message=text;kind=type;const f=$('#feedback');if(f){f.textContent=text;f.className='challenge-feedback '+type}}
  function later(ms,fn){delay=fn;delayLeft=ms/1000}
  function newQuestion(){if(g.over||disposed)return;locked=false;bad=[];g.clean=true;message='Chọn đáp án của bé nhé!';kind='';const d=difficulty();q=learning.nextFact({context:mode.id});options=choices(mode.id==='mystery'?q.b:q.answer,20);questionLeft=d.deadline;questionStarted=performance.now();renderQuestion()}
  function renderQuestion(){const d=difficulty(),mystery=mode.id==='mystery',bubble=mode.id==='bubble',rocket=mode.id==='rocket';
    $('#challenge-body').innerHTML=`<div class="play-label">CẤP ${d.level} · CỘNG & TRỪ ĐẾN 20</div><h2>${mystery?'Số nào đang trốn nhỉ?':bubble?'Chạm bong bóng đúng!':'Mình cùng tính nhé!'}</h2><div class="equation">${q.a}<span>${q.sign}</span>${mystery?'<b class="unknown">?</b>':q.b}<span>=</span>${mystery?q.answer:'<b class="unknown">?</b>'}</div>${d.deadline?'<div class="challenge-time"><span>Thời gian câu này: <b id="question-clock"></b></span><div class="progress"><div id="question-bar"></div></div></div>':''}<div class="answers ${bubble?'bubbles':''}" style="--float-speed:${d.motion}s">${options.map((v,i)=>`<button data-answer="${v}" style="--i:${i}">${v}</button>`).join('')}</div><div id="feedback" role="status" aria-live="polite" class="challenge-feedback"></div><div id="challenge-next"></div>`;
    app.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(Number(b.dataset.answer),b));if($('#hint'))$('#hint').onclick=hint;feedback(message,kind);hud();
  }
  function hint(){if(locked||paused)return;g.clean=false;g.streak=0;hud();$('#hint').disabled=true;$('#hint-content').innerHTML=`<p>${q.sign==='+'?`Đếm ${q.a} chấm, thêm ${q.b} chấm.`:`Có ${q.a} chấm, bớt ${q.b} chấm bị gạch.`} Câu có gợi ý nhận 5 điểm.</p><div class="dots">${Array.from({length:q.sign==='+'?q.answer:q.a},(_,i)=>`<i class="${q.sign==='+'?(i>=q.a?'added':''):(i>=q.answer?'removed':'')}"></i>`).join('')||'<b>Không còn chấm nào: 0</b>'}</div>`}
  function freezeAnswers(){app.querySelectorAll('[data-answer]').forEach(b=>b.disabled=true);if($('#hint'))$('#hint').disabled=true}
  function answer(value,button){if(locked||paused||disposed||g.over||bad.includes(value))return;const expected=mode.id==='mystery'?q.b:q.answer;
    if(value!==expected){bad.push(value);recordAnswer(g,false);learning.record({fact:q,result:'wrong',elapsedMs:performance.now()-questionStarted,context:mode.id,sessionId});button.disabled=true;button.classList.add('wrong','challenge-shake');showMiss(button);beep(false);feedback(g.lives!==null?'Chưa đúng. Mất 1 mạng — bé thử lại nhé!':mode.id==='rocket'?'Chưa đúng. −3 giây — bé thử lại nhé!':'Chưa đúng. Bé thử lại nhé!','miss');hud();if(g.over){locked=true;freezeAnswers();later(1000,finish)}return}
    locked=true;const points=recordAnswer(g,true);learning.record({fact:q,result:'correct',elapsedMs:performance.now()-questionStarted,context:mode.id,sessionId});award();beep();button.classList.add('right','challenge-pop');freezeAnswers();showCheck($('.unknown'),expected);if(g.streak>0&&g.streak%3===0)showStreak($('.unknown'),g.streak);feedback('','success');announce($('#feedback'),`Chính xác, +${points} điểm`);hud();
    const go=()=>{if(mode.id==='practice'&&g.correct>=12)finish();else newQuestion()};
    if(mode.id==='practice'){$('#challenge-next').innerHTML='<button class="primary" id="next">Tiếp theo →</button>';$('#next').onclick=()=>{if(!paused)go()};$('#next').focus()}else later(NEXT_DELAY_MS,go);
  }
  function timeout(){if(locked||g.over)return;locked=true;recordAnswer(g,false);learning.record({fact:q,result:'wrong',elapsedMs:performance.now()-questionStarted,context:mode.id,sessionId});freezeAnswers();beep(false);feedback(`Hết giờ! ${q.a} ${q.sign} ${q.b} = ${q.answer}. ${g.lives!==null?'Mất 1 mạng.':'−3 giây.'}`,'miss');hud();later(1700,()=>g.over?finish():newQuestion())}
  function memoryBoard(){beginMemoryBoard(g);delay=null;selected=[];matched=new Set();locked=false;g.clean=true;const d=difficulty();const unique=new Map();let tries=0;
    while(unique.size<d.pairs&&tries++<50){const x=learning.nextFact({context:'memory',excludeAnswers:[...unique.keys()]});if(x&&!unique.has(x.answer))unique.set(x.answer,x)}
    // Guaranteed finite fallback for unusually repetitive random draws.
    for(let answer=0;unique.size<d.pairs;answer++)if(!unique.has(answer))unique.set(answer,{a:answer,b:0,sign:answer%2?'−':'+',answer});
    cards=[...unique.values()].flatMap((x,i)=>[{pair:i,text:`${x.a} ${x.sign} ${x.b}`,kind:'q',fact:x},{pair:i,text:String(x.answer),kind:'a',fact:x}]);
    for(let i=cards.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[cards[i],cards[j]]=[cards[j],cards[i]]}message='Lật hai thẻ để tìm một cặp.';kind='';renderMemory();
  }
  function renderMemory(){const d=difficulty();$('#challenge-body').innerHTML=`<div class="play-label">CHẶNG ${g.board} / 3 · ${matched.size} / ${d.pairs} CẶP</div><h2>Phép tính tìm bạn</h2><p class="instructions">Mở 2 thẻ = 1 lượt ghép. Thưởng chặng tối đa ${d.pairs*10} điểm; mỗi lượt sai giảm 5 điểm thưởng.</p><div class="memory-grid">${cards.map((c,i)=>{const visible=selected.includes(i)||matched.has(c.pair);return `<button class="memory-card ${visible?'flipped':''} ${matched.has(c.pair)?'matched':''}" data-card="${i}" aria-label="${visible?c.text:'Thẻ úp '+(i+1)}" ${matched.has(c.pair)||locked?'disabled':''}>${visible?c.text:'✦'}</button>`}).join('')}</div><div id="feedback" role="status" aria-live="polite" class="challenge-feedback"></div><div id="challenge-next"></div>`;app.querySelectorAll('[data-card]').forEach(b=>b.onclick=()=>flip(Number(b.dataset.card)));feedback(message,kind);hud()}
  function flip(i){if(paused||locked||disposed||g.over||selected.includes(i)||matched.has(cards[i].pair))return;const replacingMismatch=selected.length===2;if(replacingMismatch){delay=null;message="Lật thêm một thẻ để tìm bạn nhé!";kind=""}selected=selectMemoryCard(selected,i);if(selected.length<2){renderMemory();return}const [a,b]=selected.map(j=>cards[j]),good=a.pair===b.pair&&a.kind!==b.kind;locked=good;g.clean=true;const points=recordAnswer(g,good);if(good){matched.add(a.pair);learning.record({fact:a.fact,result:'review',context:'memory',sessionId});award();beep();message=`Thành đôi! +${points} điểm`;kind='success'}else{beep(false);message='Chưa thành đôi. Có thể lật thẻ khác ngay hoặc chờ thẻ tự úp lại.';kind='miss'}if(!good){const mismatched=[...selected];renderMemory();later(1000,()=>{const next=closeMemoryMismatch(selected,mismatched);if(next===selected)return;selected=next;message='Thử một cặp khác nhé!';kind='';renderMemory()});return}selected=[];locked=false;if(matched.size===difficulty().pairs){renderMemory();const bonus=completeMemoryBoard(g);hud();if(g.board===3)finish();else{locked=true;feedback(`Xong chặng ${g.board}! Thưởng +${bonus} điểm · ${g.boardAttempts} lượt ghép. Chặng sau có ${g.board===1?4:6} cặp thẻ.`,'success');$('#challenge-next').innerHTML='<button class="primary" id="next-board">Sang chặng tiếp →</button>';$('#next-board').onclick=()=>{if(!paused){g.board++;memoryBoard()}};$('#next-board').focus()}}else renderMemory()}
  function finish(){if(disposed)return;g.over=true;locked=true;delay=null;clearInterval(clock);$('#challenge-pause').disabled=true;const d=difficulty(),recordResult=scoreSaved?{scores:scores.top(mode.id),newRecord:false,previousBest:bestAtStart}:scores.record(mode.id,g.score);scoreSaved=true;$('#challenge-body').innerHTML=`<div class="finish-icon">${recordResult.newRecord?'🏆':'🌟'}</div><h2>${recordResult.newRecord?'Kỷ lục mới!':'Hoàn thành chuyến phiêu lưu!'}</h2><p>${recordResult.newRecord?`Bé vừa vượt kỷ lục ${recordResult.previousBest} điểm. Tuyệt lắm!`:'Mỗi lần thử, bé lại giỏi hơn một chút.'}</p><div class="results"><div><b>${g.score}</b><span>Điểm</span></div><div><b>${mode.id==='memory'?g.attempts:g.bestStreak}</b><span>${mode.id==='memory'?'Lượt ghép':'Chuỗi tốt nhất'}</span></div><div><b>${d.level}</b><span>Cấp đạt được</span></div></div><div class="score-board"><h3>5 điểm cao nhất</h3>${recordResult.scores.map((x,i)=>`<span><b>${i+1}</b> ${x} điểm</span>`).join('')}</div><div class="finish-actions"><button class="primary" id="challenge-again">↻ Chơi lại</button><button class="back" id="challenge-home">Chọn trò khác</button></div>`;$('#challenge-again').onclick=restart;$('#challenge-home').onclick=home;$('#challenge-again').focus();hud()}
  function restart(){Object.assign(g,createChallenge(mode.id,20));locked=false;paused=false;delay=null;message='';kind='';scoreSaved=false;bestAtStart=scores.top(mode.id)[0]||0;sessionId=learning.newSessionId();$('#challenge-pause').disabled=false;mode.id==='memory'?memoryBoard():newQuestion();last=performance.now();clock=setInterval(tick,100)}
  function togglePause(){if(g.over||disposed)return;const now=performance.now();paused=!paused;const overlay=$('#challenge-overlay');overlay.hidden=!paused;$('#challenge-body').inert=paused;$('#challenge-pause').textContent=paused?'Tiếp tục':'Tạm dừng';last=now;if(paused){pausedAt=now;overlay.innerHTML='<h2>Mình nghỉ một chút nhé</h2><p>Trò chơi đã tạm dừng.</p><button class="primary" id="challenge-resume">Tiếp tục →</button>';$('#challenge-resume').onclick=togglePause;$('#challenge-resume').focus()}else{questionStarted+=now-pausedAt;$('#challenge-pause').focus()}}
  function visibility(){if(document.hidden&&!paused&&!g.over)togglePause()}
  function key(e){if(e.key==='Escape'&&!e.repeat){e.preventDefault();togglePause()}}
  function tick(){const now=performance.now(),dt=Math.min(.25,(now-last)/1000);last=now;if(disposed||paused||document.hidden)return;if(g.over){if(delay){delayLeft-=dt;if(delayLeft<=0){const action=delay;delay=null;action()}}return}elapse(g,dt);if(g.over){finish();return}if(delay){delayLeft-=dt;if(delayLeft<=0){const action=delay;delay=null;action()}}else if(!locked&&questionLeft!==null&&mode.id!=='memory'){questionLeft=Math.max(0,questionLeft-dt);if(!questionLeft)timeout()}hud()}
  mode.id==='memory'?memoryBoard():newQuestion();clock=setInterval(tick,100);document.addEventListener('visibilitychange',visibility);document.addEventListener('keydown',key);
  return ()=>{disposed=true;clearInterval(clock);delay=null;document.removeEventListener('visibilitychange',visibility);document.removeEventListener('keydown',key)};
}
